    r=[];p=i.get('parent')
    while p: r.append(p);p=by.get(p,{}).get('parent')
    return r
actids={i['id'] for i in act}
for i in act:
    a=anc(i)
    is_anc_of_active=any(x['id'] in [y for y in a] for x in [])
    kids=[k for k in by.values() if k.get('parent')==i['id']]
    kidst={k['status'] for k in kids}
    print(i['id'],'| leaf' if not kids else '| kids '+str(sorted(kidst)),'| owner',i.get('owner') or '-','| anc-active',[x for x in a if x in actids])
